page('Project Numazu','Explore the Numazu, Shizuoka recreation for OMSI 2.',f'''<section class="project-hero"><img src="/assets/numazu-buses.jpg" alt="Japanese buses in the Project Numazu game environment"><div><p class="eyebrow">OMSI 2 ADD-ON · AVAILABLE ON STEAM</p><h1>Project<br>Numazu.</h1><p>A journey into the streets and coastal scenery of Numazu, Shizuoka.</p><a class="button light" href="https://store.steampowered.com/app/3880120/">View on Steam ↗</a></div></section><section class="section prose"><p class="eyebrow dark">THE PROJECT</p><h2>Japan, one route at a time.</h2><p>Project Numazu brings the city’s urban core, bus routes and coastal atmosphere into OMSI 2. The team recreated familiar landmarks, streets and transit details to give players a place that feels grounded in everyday life.</p><p>Developed by Aurora Studio with collaborators including Negi-Kyu Workshop. Released March 2026.</p><div class="project-media-cta" id="current-status"><p class="eyebrow dark">CURRENT RELEASE STATUS</p><h3>Canonical release information.</h3><p>Project Numazu was released on Steam in March 2026. Aurora Studio develops the project with collaborators including Negi-Kyu Workshop. The Steam store currently lists <strong>Aerosoft GmbH</strong> as publisher.</p><p><strong>Last reviewed: 6 October 2026.</strong> Historical news posts describe the project as it stood when those posts were published. For the studio’s current public description of the released product, use this page together with the Steam store listing.</p><p><a href="https://store.steampowered.com/app/3880120/" target="_blank" rel="noopener noreferrer">Steam listing ↗</a> · <a href="https://numazukanko.jp/news/1094" target="_blank" rel="noopener noreferrer">Numazu City Tourism ↗</a> · <a href="https://www.4gamer.net/games/995/G099555/20260401038/" target="_blank" rel="noopener noreferrer">4Gamer ↗</a> · <a href="https://gnn.gamer.com.tw/detail.php?sn=302664" target="_blank" rel="noopener noreferrer">Bahamut GNN ↗</a></p></div>{numazu_gallery}<div class="project-media-cta"><p class="eyebrow dark">WATCH &amp; READ</p><h3>The journey beyond the game.</h3><p>Official trailers, coverage from 4Gamer and GNN, and recorded creator play sessions.</p><a href="/media/#numazu">Explore Project Numazu media ↗</a></div><a href="/project/">← All projects</a></section>''','project/project-numazu/index.html', game_schema('OMSI 2 Add-on: Project Numazu','https://www.aurora-studio.org/project/project-numazu/','A recreation of Numazu, Shizuoka for OMSI 2.','Simulation','Released','/assets/numazu-buses.jpg','https://store.steampowered.com/app/3880120/',publisher={'@type':'Organization','name':'Aerosoft GmbH','url':'https://www.aerosoft.com/'}))
page('About','Aurora Studio is an independent game development team based in Hong Kong.','''<section class="page-heading"><p class="eyebrow dark">ABOUT THE STUDIO</p><h1>Made in Hong Kong.<br><em>Inspired by Asia.</em></h1><p>Aurora Studio is an independent game development team based in Hong Kong.</p></section><section class="section two-column"><h2>Who we are</h2><div><p>We craft simulation and narrative-driven experiences inspired by Asia, combining cultural detail with technical precision.</p><p>Founded by Shiko Leung, the studio works with creators and partners across disciplines to bring local places and original stories to a global audience.</p><h3>Shiko Leung</h3><p>Founder &amp; Creative Director<br>Game direction, environment design, production and studio operations.</p></div></section><section class="callout"><p class="eyebrow">WORK WITH US</p><h2>Let's make something<br>memorable.</h2><a class="button light" href="/contact/">Contact the studio ↗</a></section>''','about/index.html')
page('News','Updates from Aurora Studio and its game projects.','''<section class="page-heading"><p class="eyebrow dark">FROM THE STUDIO</p><h1>News<span class="dot">.</span></h1><p>Selected announcements and milestones. Earlier articles are being restored from the previous website.</p></section><section class="section news-list"><article><time datetime="2026-09-17">17 SEP 2026</time><div><span>PROJECT UPDATE</span><h2>A Day in the Depot: Railway Depot: Operations &amp; Empire</h2><p>Introducing a management simulation about the work that keeps a railway running.</p><a href="/news/a-day-in-the-depot/">Read update ↗</a></div></article><article><time datetime="2026-03-30">30 MAR 2026</time><div><span>RELEASE</span><h2>Project Numazu is available on Steam</h2><p>Aurora Studio’s recreation of Numazu for OMSI 2 has launched.</p><a href="/news/project-numazu-is-officially-available-on-steam/">Read update ↗</a></div></article><article><time datetime="2025-12-01">01 DEC 2025</time><div><span>PROJECT UPDATE</span><h2>Project Numazu Steam page goes live</h2><p>The public store page introduced the team’s Japanese city simulation to players.</p><a href="/news/omsi-2-add-on-project-numazu-steam-page-now-live/">Read update ↗</a></div></article></section>''','news/index.html')
page('Contact','Get in touch with Aurora Studio for press, partnerships and project enquiries.','''<section class="page-heading"><p class="eyebrow dark">CONTACT</p><h1>Let's talk<span class="dot">.</span></h1><p>For coverage, partnerships or a conversation about our work, write to the studio directly.</p></section><section class="section contact-grid"><a href="mailto:press@aurora-studio.org"><span>PRESS &amp; PARTNERSHIPS</span><h2>press@aurora-studio.org</h2><b>↗</b></a><a href="mailto:support@aurora-studio.org"><span>PLAYER SUPPORT</span><h2>support@aurora-studio.org</h2><b>↗</b></a></section>''','contact/index.html')
page('Revenant of Tsushima','An Edo-period folk horror journey starring Tsushima Mewa.','''<figure class="rot-poster"><img src="/assets/revenant-cover-v2.jpg" alt="Revenant of Tsushima artwork featuring Tsushima Mewa, spirits and a moonlit Japanese landscape" fetchpriority="high"></figure><section class="page-heading"><p class="eyebrow dark">ORIGINAL GAME · IN DEVELOPMENT</p><h1>Revenant of<br>Tsushima<span class="dot">.</span></h1><p>Japanese folk horror on a journey through the Tōkaidō.</p></section><section class="section two-column"><h2>A world awakened</h2><div><p>Tsushima Mewa, a shrine maiden sealed for more than three centuries, awakens to a world of yōkai. The player travels through shrines, villages, mountain passes and the coast, using Ether Sight and rituals to face supernatural threats.</p><p>This original first-person project is in development in Unreal Engine 5. Game features and scope may change.</p><a class="button light" href="https://revenant-tsushima.aurora-studio.org/">Official game website ↗</a><p><a class="inline-media-link" href="/media/#revenant">Watch the official teaser ↗</a></p></div></section>''','project/revenant-of-tsushima/index.html', game_schema('Revenant of Tsushima','https://www.aurora-studio.org/project/revenant-of-tsushima/','A first-person Edo-period Japanese folk horror journey starring Tsushima Mewa.','Folk horror','In development','/assets/revenant-cover-v2.jpg','https://revenant-tsushima.aurora-studio.org/'))
page('Railway Depot: Operations & Empire','A pre-alpha railway depot operations game by Aurora Studio.','''<section class="page-heading"><p class="eyebrow dark">MANAGEMENT SIM · PRE-ALPHA</p><h1>Railway<br>Depot<span class="dot">.</span></h1><p>You don't just drive the trains. You run the railway behind them.</p></section><section class="section two-column"><h2>Run the day behind the trains.</h2><div><p>Prepare trains, coordinate maintenance, assign people and dispatch services. Railway Depot: Operations &amp; Empire is an early-stage operations and management game inspired by East Asian railway culture.</p><p>A pre-alpha build is available for feedback. Systems and visuals are subject to change.</p><a class="button light" href="https://shikosama.itch.io/railway-depot">Explore on itch.io ↗</a></div></section>''','project/railway-depot/index.html', game_schema('Railway Depot: Operations & Empire','https://www.aurora-studio.org/project/railway-depot/','A railway depot operations and management simulation.','Management simulation','Pre-alpha'))
page('Aurora Engine','Aurora Engine is an experimental modular C++ and Unreal NPC systems framework.','''<section class="page-heading"><p class="eyebrow dark">R&amp;D · OPEN DEVELOPMENT</p><h1>Aurora Engine<span class="dot">.</span></h1><p>A modular framework for agents that see, learn, remember and act.</p></section><section class="section two-column"><h2>Systems for lived-in worlds.</h2><div><p>Aurora Engine explores how game characters perceive their surroundings, retain knowledge and make decisions within a designer-directed world. The project includes a C++ core and Unreal integration work.</p><p>This is active research and development, not a shipped game.</p><a class="button light" href="https://github.com/Shiko215/aurora-engine">See the source ↗</a></div></section>''','project/aurora-engine/index.html')
