acg_news_title = 'Aurora Studio launches cross-border ACG partnership service'
acg_news_summary = 'A Hong Kong-based practice helps brands and venues shape ACG collaborations across the Greater Bay Area, Japan and international markets.'
acg_news_url = 'https://www.aurora-studio.org/news/acg-partnerships-launch/'
page(acg_news_title, acg_news_summary,
     '''<section class="page-heading news-heading"><p class="eyebrow dark">STUDIO ANNOUNCEMENT · <time datetime="2026-09-28">28 SEPTEMBER 2026</time></p>
     <h1 class="article-title">Aurora Studio launches cross-border ACG partnership service.</h1>
     <p>Connecting the right creative idea with the right market.</p></section>
     <article class="section article">
     <p><strong>HONG KONG, 28 September 2026</strong> — Aurora Studio has launched an ACG partnership strategy and local production service for brands, venues, tourism and cultural teams, game publishers and entertainment businesses seeking to connect Hong Kong and the Greater Bay Area with Japan and international creative markets.</p>
     <p>The service helps clients turn an initial objective into a proposal that potential collaborators can evaluate. Work can include audience and IP fit, partnership concepts, campaign formats, commercial briefs, outreach to prospective rights holders where appropriate, localization, local activation planning, and creator and media coordination.</p>
     <p>Possible formats range from pop-ups and exhibitions to retail, food and beverage concepts, fan experiences and interactive campaigns. Each proposal is scoped around its audience, venue, schedule, budget, rights and production requirements. Aurora Studio works with suitable production partners where a project calls for specialist delivery.</p>
     <p>The practice builds on Aurora Studio's experience in game development, international publishing communication and cross-market promotion. Its OMSI 2 add-on <a href="/project/project-numazu/">Project Numazu</a> is a public example of a place-based project developed for audiences across markets, with creator activity and coverage in Japanese and Taiwanese game media.</p>
     <p>Prospective clients can begin by sharing the audience they want to reach, the proposed location and campaign window, an indicative budget range, and the intended outcome. The studio will then discuss a defined discovery or production brief before any approach to a rights holder or vendor.</p>
     <p><strong>About Aurora Studio</strong><br>Aurora Studio is an independent game development studio based in Hong Kong. It creates simulation and narrative experiences inspired by the places and stories of East Asia, and undertakes selected creative and cross-border collaborations.</p>
     <p><strong>Press and partnership enquiries:</strong> <a href="mailto:press@aurora-studio.org">press@aurora-studio.org</a></p>
     <p><small>All IP, talent and brand collaborations depend on the relevant rights holders' interest, approvals, availability and agreed commercial terms. Aurora Studio does not represent or guarantee access to any third-party IP.</small></p>
     <div class="article-links"><a href="/acg-partnerships/">Explore the partnership service ↗</a><a href="/news/">← All news</a></div>
     </article>''',
     'news/acg-partnerships-launch/index.html',
     news_schema(acg_news_title, acg_news_url, acg_news_summary, '2026-09-28', '/assets/numazu-route.jpg'))


openomsi_news_title = 'Aurora Studio expands upstream technical contributions to openOMSI'
openomsi_news_summary = 'Project Numazu is being used as a production-scale compatibility testbed as Aurora Studio contributes fixes and Asian localisation to the open-source simulator.'
openomsi_news_url = 'https://www.aurora-studio.org/news/aurora-openomsi-technical-contributions/'
page(openomsi_news_title, openomsi_news_summary,
     '''<section class="page-heading news-heading"><p class="eyebrow dark">TECHNICAL CONTRIBUTION · <time datetime="2026-10-01">1 OCTOBER 2026</time></p>
     <h1 class="article-title">Aurora Studio expands upstream technical contributions to openOMSI.</h1>
     <p>Commercial OMSI experience meets open-source compatibility work.</p></section>
     <article class="section article">
     <figure style="margin:0 0 2rem"><img style="width:100%;height:auto;display:block" width="1920" height="1080" class="article-visual" src="/assets/openomsi/openomsi-numazu-fish-market.webp" alt="Project Numazu running in Aurora Studio’s recent openOMSI compatibility workflow at Numazu Fish Market" loading="lazy"><figcaption><small>Recent Project Numazu runtime screenshot used in Aurora Studio’s openOMSI compatibility workflow. Numazu Fish Market, September 2026.</small></figcaption></figure>
     <p><strong>HONG KONG, 1 October 2026</strong> — Aurora Studio has expanded its technical involvement in <a href="https://github.com/turbo-devv/openOMSI" target="_blank" rel="noopener noreferrer">openOMSI</a>, contributing upstream compatibility fixes and Asian interface localisation while testing existing OMSI content, including <a href="/project/project-numazu/">OMSI 2 Add-on: Project Numazu</a>, against the emerging open-source simulator.</p>
     <p>Project Numazu combines a large map, scenery objects, passenger assets, AI traffic, scripts and legacy OMSI behaviours. Aurora Studio is using that production-scale content as a practical compatibility testbed: when a problem appears, the studio investigates whether it is specific to the add-on or reflects a wider OMSI behaviour that may affect other maps and vehicles.</p>
     <h2>Upstream work already merged</h2>
     <p>Since 29 September 2026, Aurora Studio founder Shiko Leung, contributing on GitHub as <strong>Shiko215</strong>, has submitted six substantive pull requests to the upstream <strong>turbo-devv/openOMSI</strong> repository. Five had been merged by 1 October, with one further compatibility change under review.</p>
     <ul>
       <li><a href="https://github.com/turbo-devv/openOMSI/pull/88" target="_blank" rel="noopener noreferrer">PR #88</a> — Asian interface localisation contributed by Aurora Studio.</li>
       <li><a href="https://github.com/turbo-devv/openOMSI/pull/103" target="_blank" rel="noopener noreferrer">PR #103</a> — indexed parking lists, scenery free textures and decorative splines.</li>
       <li><a href="https://github.com/turbo-devv/openOMSI/pull/198" target="_blank" rel="noopener noreferrer">PR #198</a> — scenery free-texture filenames produced in frame scripts.</li>
       <li><a href="https://github.com/turbo-devv/openOMSI/pull/199" target="_blank" rel="noopener noreferrer">PR #199</a> — low-density random traffic compatibility.</li>
       <li><a href="https://github.com/turbo-devv/openOMSI/pull/201" target="_blank" rel="noopener noreferrer">PR #201</a> — preserving AI pool rules through random traffic routing.</li>
       <li><a href="https://github.com/turbo-devv/openOMSI/pull/455" target="_blank" rel="noopener noreferrer">PR #455</a> — map-specific nested passenger-pack compatibility, under review at the time of publication.</li>
     </ul>
     <h2>From commercial add-on development to ecosystem compatibility</h2>
     <p>The purpose of this work is broader than making one add-on run. Commercial OMSI content exposes combinations of assets and legacy behaviours that can be difficult to reproduce in a small test scene. By tracing those cases and contributing suitable fixes upstream, Aurora Studio aims to help openOMSI interpret more of the existing OMSI ecosystem faithfully.</p>
     <p>The studio is also contributing from an Asian development perspective. Interface localisation and compatibility testing with Japanese transport content can help reduce barriers for users and creators whose OMSI libraries extend beyond the simulator's original European focus.</p>
     <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin:2rem 0">
       <figure style="margin:0"><img width="1920" height="1080" src="/assets/openomsi/openomsi-numazu-station-sunset.webp" alt="Project Numazu at Numazu Station during Aurora Studio’s openOMSI compatibility testing" loading="lazy" style="width:100%;height:auto;display:block"><figcaption><small>Project Numazu at Numazu Station during recent openOMSI compatibility testing.</small></figcaption></figure>
       <figure style="margin:0"><img width="1920" height="1080" src="/assets/openomsi/openomsi-numazu-shinkin-bank.webp" alt="Project Numazu Japanese streetscape during Aurora Studio’s openOMSI compatibility testing" loading="lazy" style="width:100%;height:auto;display:block"><figcaption><small>Japanese streetscape content provides real-world cases for openOMSI compatibility and localisation work.</small></figcaption></figure>
       <figure style="margin:0"><img width="1920" height="1080" src="/assets/openomsi/openomsi-numazu-harbour-street.webp" alt="A bus beside Japanese harbour-side buildings in Project Numazu during openOMSI compatibility testing" loading="lazy" style="width:100%;height:auto;display:block"><figcaption><small>Harbour-side buildings and traffic provide additional scenery and vehicle compatibility test cases.</small></figcaption></figure>
     </div>
     <h2>An independent open-source project</h2>
     <p><strong>openOMSI is an independent open-source project.</strong> Aurora Studio's current involvement is as an upstream contributor through compatibility testing, localisation and code contributions. This announcement does not describe Aurora Studio as the owner, operator or official technology partner of openOMSI.</p>
     <p>Project Numazu remains a commercial OMSI 2 add-on distributed through its existing publishing channels. Aurora Studio intends to continue testing relevant OMSI content and contributing suitable fixes where they can benefit the wider community.</p>
     <p><strong>Press and technical enquiries:</strong> <a href="mailto:press@aurora-studio.org">press@aurora-studio.org</a></p>
     <div class="article-links"><a href="https://github.com/turbo-devv/openOMSI" target="_blank" rel="noopener noreferrer">Explore openOMSI on GitHub ↗</a><a href="/project/project-numazu/">Explore Project Numazu ↗</a><a href="/news/">← All news</a></div>
     </article>''',
     'news/aurora-openomsi-technical-contributions/index.html',
     news_schema(openomsi_news_title, openomsi_news_url, openomsi_news_summary, '2026-10-01', '/assets/openomsi/openomsi-numazu-fish-market.webp'))

